use crate::loudness::{Loudness, Normalized, Target, measure, normalize};
use crate::manifest::{ClipKind, PackNames, manifest_split_in};
use crate::sources::{SiteNames, site_names};
use crate::tokenizer::PocketText;
use crate::tts::{PocketTts, SAMPLE_RATE, Utterance};

/// Layer name of the French voice (the English one is `voice-en`, [`Lang::layer`]).
pub const LAYER: &str = "voice";
/// Token budget of one clip (pockettts.cpp chunk budget, speak measurement).
pub const MAX_TOKENS: usize = 50;
/// Seeds tried for a clip: the configured one, then the next ones.
pub const SEED_ATTEMPTS: u32 = 8;
/// File of the voice layer that lists the clips of personal names ([`PersonalClips`]).
pub const PERSONAL_FILE: &str = "personal.json";

/// Generation settings.
#[derive(Debug, Clone)]
pub struct VoiceConfig {
    /// Language of the clips.
    pub lang: Lang,
    /// Text-to-speech.
    pub tts: PocketTts,
    /// French text-to-speech for the French proper names of a voice in another language
    /// (`None` for the French voice): same speaker, French model ([`clip_parts`]).
    pub names_tts: Option<PocketTts>,
    /// Encoder.
    pub ffmpeg: Ffmpeg,
    /// Trimming and level of each synthesised part.
    pub shape: Shape,
    /// Loudness of the clips (#179): every clip brought to the same loudness and peak
    /// ceiling before encoding, checked on the decoded file.
    pub loudness: Target,
}

fn env_path(var: &str, default: impl FnOnce() -> PathBuf) -> PathBuf {
    std::env::var_os(var).map_or_else(default, PathBuf::from)
}

impl VoiceConfig {
    /// French voice from the environment ([`VoiceConfig::from_env_lang`]).
    pub fn from_env() -> Result<Self> {
        Self::from_env_lang(Lang::Fr)
    }

    /// Voice of `lang` from the environment, with the defaults of this workstation
    /// (`<language>` is `french` or `english`; the variables of the English voice end with
    /// `_EN`: `SKIMAP_POCKETTTS_MODEL_EN`, `SKIMAP_POCKETTTS_VOICES_EN`, `SKIMAP_VOICE_EN`):
    ///
    /// | Variable | Default |
    /// |---|---|
    /// | `SKIMAP_POCKETTTS_BIN` | `~/.cache/skimap/pockettts/build-cuda/pocket-tts` |
    /// | `SKIMAP_POCKETTTS_MODEL` | `~/projects/speak/app/models/tts/pocket-tts-<language>-Q8_0.gguf` |
    /// | `SKIMAP_POCKETTTS_VOICES` | `~/projects/speak/app/models/tts/pocket-tts-<language>-voices.gguf` |
    /// | `SKIMAP_VOICE` | [`default_voice`] |
    /// | `SKIMAP_TTS_DEVICE` | best device (CUDA0 here) |
    /// | `SKIMAP_TTS_SEED` | `42` |
    /// | `SKIMAP_FFMPEG` | `ffmpeg` |
    /// | `SKIMAP_OPUS_KBPS` | `24` |
    pub fn from_env_lang(lang: Lang) -> Result<Self> {
        let suffix = match lang {
            Lang::Fr => "",
            Lang::En => "_EN",
        };
        let language = match lang {
            Lang::Fr => "french",
            Lang::En => "english",
        };
        let var = |v: &str| format!("{v}{suffix}");
        // HOME only for the defaults of the workstation: the pipeline image sets every
        // path (deploy/Dockerfile) and its user has no home.
        let home = std::env::var_os("HOME")
            .map(PathBuf::from)
            .unwrap_or_default();
        let tts_dir = home.join("projects/speak/app/models/tts");
        let num = |var: &str, default: u32| -> Result<u32> {
            match std::env::var(var) {
                Ok(v) => v
                    .parse()
                    .map_err(|_| Error::Config(format!("{var}={v} is not a number"))),
                Err(_) => Ok(default),
            }
        };
        let names_tts = match lang {
            Lang::Fr => None,
            _ => Some(Self::from_env_lang(Lang::Fr)?.tts),
        };
        Ok(Self {
            lang,
            names_tts,
            tts: PocketTts {
                binary: env_path("SKIMAP_POCKETTTS_BIN", || {
                    home.join(".cache/skimap/pockettts/build-cuda/pocket-tts")
                }),
                model: env_path(&var("SKIMAP_POCKETTTS_MODEL"), || {
                    tts_dir.join(format!("pocket-tts-{language}-Q8_0.gguf"))
                }),
                voices: env_path(&var("SKIMAP_POCKETTTS_VOICES"), || {
                    tts_dir.join(format!("pocket-tts-{language}-voices.gguf"))
                }),
                voice: std::env::var(var("SKIMAP_VOICE"))
                    .unwrap_or_else(|_| default_voice(lang).into()),
                device: std::env::var("SKIMAP_TTS_DEVICE").ok(),
                seed: num("SKIMAP_TTS_SEED", 42)?,
            },
            ffmpeg: Ffmpeg {
                binary: env_path("SKIMAP_FFMPEG", || PathBuf::from("ffmpeg")),
                kbps: num("SKIMAP_OPUS_KBPS", 24)?,
            },
            shape: Shape::default(),
            loudness: Target::default(),
        })
    }
}

/// Voice of the clips of `lang`: `estelle` in both languages, the same speaker in French
/// and in English; the French names of an English pack are said by the French model
/// ([`clip_parts`]; transcription measurements in `docs/voix/anglais.md`).
pub fn default_voice(lang: Lang) -> &'static str {
    match lang {
        Lang::Fr | Lang::En => "estelle",
    }
}

/// What is synthesised for a clip: `(engine, text)` parts, played in order with a short
/// pause; engine 0 is the voice of the language, 1 the French voice
/// ([`VoiceConfig::names_tts`]). In another language than French, a name clip is the name
/// said by the French voice (a French proper name pronounced as in French), then for a
/// piste its colour in the language: « Greffier. » (French) + « Black trail. » (English).
pub fn clip_parts(id: &str, kind: ClipKind, text: &str, cfg: &VoiceConfig) -> Vec<(usize, String)> {
    use crate::clips::{Clip, capitalise};
    use crate::phrase::Phrase;
    if kind != ClipKind::Name || cfg.names_tts.is_none() {
        return vec![(0, text.to_owned())];
    }
    let c = Clip {
        id: id.to_owned(),
        text: text.to_owned(),
    };
    match Phrase::parse(&c, cfg.lang) {
        Some(Phrase::Piste {
            spoken,
            colour: Some(col),
            ..
        }) => vec![
            (1, format!("{spoken}.")),
            (0, format!("{} trail.", capitalise(crate::en::colour(col)))),
        ],
        Some(Phrase::Piste { spoken, .. } | Phrase::Place { spoken, .. }) => {
            vec![(1, format!("{spoken}."))]
        }
        _ => vec![(0, text.to_owned())],
    }
}

/// One clip in `manifest.json`.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ClipEntry {
    /// Clip id.
    pub id: String,
    /// Kind.
    pub kind: ClipKind,
    /// Text spoken.
    pub text: String,
    /// File, relative to the layer directory.
    pub file: String,
    /// Duration after trimming, ms.
    pub duration_ms: u32,
    /// File size, bytes.
    pub bytes: u64,
    /// Pocket TTS tokens (checked against the pockettts.cpp log).
    pub tokens: usize,
    /// Leading silence removed, ms.
    pub lead_trim_ms: u32,
    /// Trailing silence removed, ms.
    pub tail_trim_ms: u32,
    /// Gain applied to the synthesised audio, dB (level of the parts, then loudness).
    pub gain_db: f64,
    /// Whether a cut-off sound at the end of the generated audio was removed.
    pub end_burst: bool,
    /// Noise seed of the kept generation.
    pub seed: u32,
    /// Speech still starts before `MIN_ONSET_MS` after every seed tried (onset maybe cut).
    pub onset_clipped: bool,
    /// Integrated loudness of the decoded file, LUFS (`None`: layer built before #179).
    #[serde(default)]
    pub loudness_lufs: Option<f64>,
    /// True peak of the decoded file, dBTP (`None`: layer built before #179).
    #[serde(default)]
    pub true_peak_dbtp: Option<f64>,
    /// Largest gain reduction of the peak limiter, dB (0: not limited).
    #[serde(default)]
    pub limiter_db: Option<f64>,
    /// The limiter reached its bound: the clip is a little under the target loudness.
    #[serde(default)]
    pub loudness_capped: bool,
}

/// `personal.json` of the voice layer: the clips that speak a name read only from
/// personal-use sources (Biodiv'sports, piste plans), left out of a published pack.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct PersonalClips {
    /// Why.
    pub note: String,
    /// Names of the personal-use sources of these names.
    pub sources: Vec<String>,
    /// Clip ids, sorted.
    pub clips: Vec<String>,
}

impl PersonalClips {
    /// Reads `personal.json` from a voice layer directory (`None` if absent).
    pub fn read(dir: &Path) -> Result<Option<Self>> {
        let p = dir.join(PERSONAL_FILE);
        if !p.is_file() {
            return Ok(None);
        }
        let b = std::fs::read(&p).map_err(|e| Error::io(&p, e))?;
        serde_json::from_slice(&b)
            .map(Some)
            .map_err(|source| Error::Json { path: p, source })
    }

    /// Whether a clip is personal.
    pub fn contains(&self, id: &str) -> bool {
        self.clips.binary_search_by(|c| c.as_str().cmp(id)).is_ok()
    }
}

/// `manifest.json` of the voice layer.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct VoiceManifest {
    /// Format version.
    pub format: u32,
    /// Language of the texts and clips (`fr` for layers built before VO6).
    #[serde(default = "french")]
    pub lang: Lang,
    /// Voice name.
    pub voice: String,
    /// Model file name.
    pub model: String,
    /// SHA-256 of the model file.
    pub model_sha256: String,
    /// First noise seed (clips that needed another one record theirs).
    pub seed: u32,
    /// Sample rate of the clips before encoding, Hz.
    pub sample_rate: u32,
    /// Opus bitrate, kbit/s.
    pub opus_kbps: u32,
    /// Loudness of every clip, LUFS, and highest true peak, dBTP (`None`: built before #179).
    #[serde(default)]
    pub loudness_target: Option<(f64, f64)>,
    /// Pause durations, ms: short (inside a message), long (between messages).
    pub pauses_ms: (u32, u32),
    /// Clips, sorted by id.
    pub clips: Vec<ClipEntry>,
}

fn french() -> Lang {
    Lang::Fr
}

impl VoiceManifest {
    /// Reads `manifest.json` from a voice layer directory.
    pub fn read(dir: &Path) -> Result<Self> {
        let p = dir.join("manifest.json");
        let b = std::fs::read(&p).map_err(|e| Error::io(&p, e))?;
        serde_json::from_slice(&b).map_err(|source| Error::Json { path: p, source })
    }

    /// Entry of a clip id.
    pub fn get(&self, id: &str) -> Option<&ClipEntry> {
        self.clips
            .binary_search_by(|c| c.id.as_str().cmp(id))
            .ok()
            .map(|i| &self.clips[i])
    }
}

/// Sources of the voice itself (model, voice, engine), for `voice.meta.json`.
pub fn voice_sources(voice: &str, lang: Lang) -> Vec<SourceRef> {
    let (model, dir) = match lang {
        Lang::Fr => ("modèle français 6 couches (pack d'octobre)", "french"),
        Lang::En => ("modèle anglais (pack d'octobre)", "english"),
    };
    let mut s = vec![
        SourceRef::new(
            format!("Pocket TTS, {model}, converti en GGUF Q8_0"),
            format!("https://huggingface.co/kyutai/pocket-tts-without-voice-cloning/tree/08ffc58775e62aad9409511b9591c9af626270f3/languages/{dir}"),
            "CC-BY-4.0, avec les usages interdits de Kyutai (pas de clonage sans consentement, pas de contenu trompeur)",
            "Voix de synthèse : Pocket TTS, Kyutai",
        )
        .producer("Kyutai")
        .edition("08ffc58"),
        SourceRef::new(
            "pockettts.cpp fab79722 + patchs speak 0001-0008",
            "https://github.com/ServeurpersoCom/pockettts.cpp",
            "MIT",
            "pockettts.cpp",
        )
        .edition("fab79722"),
    ];
    if voice == "estelle" {
        s.push(SourceRef::new(
            "Voix estelle (unmute-prod-website/developpeuse-3.wav)",
            "https://huggingface.co/kyutai/tts-voices",
            "CC0 (enregistrement de Kyutai)",
            "Voix estelle, Kyutai",
        ));
    }
    s
}

/// Source name of the clip cache in the data directory (`cache/voice/`, [`ClipCache`]).
pub const CACHE_SOURCE: &str = "voice";
/// Version of the cache format and of what a clip is made of: changed, every clip is
/// made again. 2: loudness normalisation of #179 (a clip of format 1 is at the level of
/// the parts, about -21 LUFS).
pub const CACHE_FORMAT: u32 = 2;

/// What an engine is for the cache: its model, voices, voice and first seed (not the
/// device: the same model gives the same speech on the GPU of the workstation and on the
/// CPU of the server).
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct EngineKey {
    /// SHA-256 of the model file.
    pub model_sha256: String,
    /// SHA-256 of the voices file.
    pub voices_sha256: String,
    /// Voice name.
    pub voice: String,
    /// First noise seed.
    pub seed: u32,
}

impl EngineKey {
    /// Key of `tts` (the model files are hashed once per process while unchanged).
    pub fn of(tts: &PocketTts) -> Result<Self> {
        Ok(Self {
            model_sha256: sha256_file_cached(&tts.model)?,
            voices_sha256: sha256_file_cached(&tts.voices)?,
            voice: tts.voice.clone(),
            seed: tts.seed,
        })
    }
}

/// Cache key of a clip made of `parts` (engine, text), played in order with the short
/// pause: every setting the audio depends on (seeds tried, onset threshold, trimming and
/// level, sample rate, bitrate, pause, and the loudness normalisation of #179: target,
/// peak ceiling, tolerance, limiter, version of the algorithm, rate of the check).
pub fn clip_key(parts: &[(&EngineKey, &str)], cfg: &VoiceConfig) -> String {
    hex::encode(Sha256::digest(
        clip_key_inputs(parts, cfg).to_string().as_bytes(),
    ))
}

/// What [`clip_key`] hashes.
fn clip_key_inputs(parts: &[(&EngineKey, &str)], cfg: &VoiceConfig) -> serde_json::Value {
    serde_json::json!({
        "format": CACHE_FORMAT,
        "parts": parts,
        "seed_attempts": SEED_ATTEMPTS,
        "min_onset_ms": MIN_ONSET_MS,
        "shape": format!("{:?}", cfg.shape),
        "sample_rate": SAMPLE_RATE,
        "opus_kbps": cfg.ffmpeg.kbps,
        "gap_ms": crate::bank::Pause::Short.ms(),
        "loudness": loudness_key(&cfg.loudness),
    })
}

/// What the loudness of a clip depends on, for [`clip_key`] and [`code_revision`]: every
/// field of the target (`{:?}` of `f64` round-trips: two targets differ here exactly when
/// they differ), the version of [`normalize`] and of [`encode_levelled`], and the rate
/// the decoded file is checked at.
fn loudness_key(t: &Target) -> serde_json::Value {
    serde_json::json!({
        "target": format!("{t:?}"),
        "algorithm": crate::loudness::ALGORITHM_VERSION,
        "attempts": LEVEL_ATTEMPTS,
        "measure_rate": MEASURE_RATE,
    })
}

/// Fingerprint of what the voice layer of `lang` is made of besides the names of the
/// site (#129, the code fingerprint of the `voice` steps of `build-all`): the cache
/// format, every phrase of the bank and how sample names of each kind are spoken and cut
/// in parts, and the engines of `cfg` (`None`: no engine configured). A change runs the
/// voice of every site again; the clips that did not change come from the cache.
pub fn code_revision(lang: Lang, cfg: Option<&VoiceConfig>) -> String {
    use crate::names::{Colour, PisteName};
    let sample = PackNames {
        site: "Échantillon".into(),
        pistes: vec![
            PisteName::new("Échantillon", Some(Colour::Green)),
            PisteName::new("Échantillon", Some(Colour::Blue)),
            PisteName::new("Échantillon", Some(Colour::Red)),
            PisteName::new("Échantillon", Some(Colour::Black)),
            PisteName::new("Échantillon", None),
        ],
        places: vec!["Refuge de l'Échantillon".into()],
        dates: vec![
            crate::clips::DayMonth { day: 15, month: 1 },
            crate::clips::DayMonth { day: 31, month: 12 },
        ],
        status_pistes: 3,
    };
    let m = manifest_split_in(&sample, &PackNames::default(), lang);
    let mut h = Sha256::new();
    h.update(CACHE_FORMAT.to_le_bytes());
    h.update(lang.code().as_bytes());
    for (id, (kind, text)) in &m.clips {
        h.update(format!("{id}\0{kind:?}\0{text}\0").as_bytes());
        if let Some(cfg) = cfg {
            for (engine, part) in clip_parts(id, *kind, text, cfg) {
                h.update(format!("{engine}\0{part}\0").as_bytes());
            }
        }
    }
    match cfg {
        Some(cfg) => {
            let mut engines = vec![&cfg.tts];
            engines.extend(&cfg.names_tts);
            for e in engines {
                match EngineKey::of(e) {
                    Ok(k) => h.update(format!("{k:?}").as_bytes()),
                    Err(_) => h.update(b"engine files missing"),
                }
            }
            h.update(format!("{:?}{}", cfg.shape, cfg.ffmpeg.kbps).as_bytes());
            h.update(loudness_key(&cfg.loudness).to_string().as_bytes());
        }
        None => h.update(b"no engine"),
    }
    hex::encode(h.finalize())
}

/// A clip of the cache: what its manifest entry says of its audio.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct CachedClip {
    /// Duration after trimming, ms.
    pub duration_ms: u32,
    /// Size of the Ogg/Opus file, bytes.
    pub bytes: u64,
    /// Pocket TTS tokens.
    pub tokens: usize,
    /// Leading silence removed, ms.
    pub lead_trim_ms: u32,
    /// Trailing silence removed, ms.
    pub tail_trim_ms: u32,
    /// Gain applied to the synthesised audio, dB (level of the first part, then loudness).
    pub gain_db: f64,
    /// Whether a cut-off sound at the end was removed.
    pub end_burst: bool,
    /// Noise seed of the kept generation (of the first part).
    pub seed: u32,
    /// Onset maybe cut after every seed tried.
    pub onset_clipped: bool,
    /// Integrated loudness of the decoded file, LUFS (#179). Required: the description of
    /// a clip cached before the loudness normalisation does not read, the clip is made
    /// again.
    pub loudness_lufs: f64,
    /// True peak of the decoded file, dBTP.
    pub true_peak_dbtp: f64,
    /// Largest gain reduction of the peak limiter, dB (0: not limited).
    pub limiter_db: f64,
    /// The limiter reached its bound: the clip is a little under the target loudness.
    pub loudness_capped: bool,
}

/// Clips already made, shared by every site and language of the data directory
/// (`cache/voice/clips/<k[..2]>/<k>.opus` and `<k>.json`, `k` = [`clip_key`]): the
/// voice layer of a site synthesises only the phrases absent from it (#129). The JSON is
/// written after the audio: a clip is in the cache once both are, with the size the JSON
/// gives.
#[derive(Debug, Clone)]
pub struct ClipCache {
    dir: PathBuf,
}

impl ClipCache {
    /// The cache of `layout`.
    pub fn new(layout: &DataLayout) -> Result<Self> {
        Ok(Self {
            dir: layout.cache_dir(CACHE_SOURCE)?,
        })
    }

    fn paths(&self, key: &str) -> (PathBuf, PathBuf) {
        let d = self.dir.join("clips").join(&key[..2]);
        (d.join(format!("{key}.opus")), d.join(format!("{key}.json")))
    }

    /// Lock file taken while clips are synthesised for the cache.
    pub fn lock_path(&self) -> PathBuf {
        self.dir.join("synthesis.lock")
    }

    /// The clip of `key`, when it is in the cache whole.
    pub fn get(&self, key: &str) -> Option<CachedClip> {
        let (opus, json) = self.paths(key);
        let c: CachedClip = serde_json::from_slice(&std::fs::read(json).ok()?).ok()?;
        (std::fs::metadata(opus).ok()?.len() == c.bytes).then_some(c)
    }

    /// Brings `samples` to the loudness target of `cfg` and encodes them as the clip `id`
    /// of `key` (levelled, encoded, checked once decoded, levelled again when off the
    /// target), described by `c`: its size, loudness and the loudness gain (added to
    /// `c.gain_db`, the level of the parts) are set here.
    pub fn put(
        &self,
        id: &str,
        key: &str,
        samples: &[i16],
        mut c: CachedClip,
        cfg: &VoiceConfig,
    ) -> Result<CachedClip> {
        let (opus, json) = self.paths(key);
        let f = skimap_common::output::AtomicFile::create(&opus)?;
        let (level, decoded) = encode_levelled(id, samples, f.tmp(), cfg)?;
        c.bytes = f.commit()?;
        c.gain_db = ((c.gain_db + level.gain_db) * 10.0).round() / 10.0;
        c.loudness_lufs = round2(decoded.lufs);
        c.true_peak_dbtp = round2(decoded.true_peak_dbtp);
        c.limiter_db = round2(level.limiter_db);
        c.loudness_capped = level.capped;
        write_json(&json, &c)?;
        Ok(c)
    }

    /// Copies the clip of `key` to `to` (a file of a voice layer).
    pub fn copy_to(&self, key: &str, c: &CachedClip, to: &Path) -> Result<()> {
        let (opus, _) = self.paths(key);
        let n = skimap_common::output::copy_file(&opus, to)?;
        if n != c.bytes {
            return Err(Error::Clip {
                id: key.to_owned(),
                message: format!("cached clip of {n} bytes, {} expected", c.bytes),
            });
        }
        Ok(())
    }
}

/// [`sha256_file`] once per process for a file whose size and modification time did not
/// change (the 300 MB of a model, for each language of each site).
fn sha256_file_cached(p: &Path) -> Result<String> {
    use std::collections::HashMap;
    use std::sync::{Mutex, OnceLock};
    type Seen = HashMap<PathBuf, (u64, Option<std::time::SystemTime>, String)>;
    static SEEN: OnceLock<Mutex<Seen>> = OnceLock::new();
    let m = std::fs::metadata(p).map_err(|e| Error::io(p, e))?;
    let stamp = (m.len(), m.modified().ok());
    let seen = SEEN.get_or_init(Mutex::default);
    if let Some((n, t, h)) = seen.lock().expect("hash memo").get(p)
        && (*n, *t) == stamp
    {
        return Ok(h.clone());
    }
    let h = sha256_file(p)?;
    seen.lock()
        .expect("hash memo")
        .insert(p.to_owned(), (stamp.0, stamp.1, h.clone()));
    Ok(h)
}

/// Summary of a build.
#[derive(Debug, Clone, Serialize)]
pub struct VoiceBuild {
    /// Layer directory.
    pub dir: PathBuf,
    /// Clips per kind: (count, bytes, audio ms).
    pub per_kind: Vec<(ClipKind, usize, u64, u64)>,
    /// All clips: bytes.
    pub total_bytes: u64,
    /// All clips: audio, s.
    pub total_audio_s: f64,
    /// Largest token count of a clip.
    pub max_tokens: usize,
    /// Leading silence removed: min, median, max, ms.
    pub lead_trim_ms: (u32, u32, u32),
    /// Clips whose cut-off final sound was removed.
    pub end_bursts: usize,
    /// Units (distinct texts of an engine) synthesised in each pass (pass k uses seed +
    /// k); empty when every clip came from the cache.
    pub passes: Vec<usize>,
    /// Clips made by this build (#129: the others came from the cache, [`ClipCache`]).
    pub made_clips: usize,
    /// Clips taken from the cache, made before for this site or another one.
    pub reused_clips: usize,
    /// Clips whose onset is still at the start after every seed.
    pub onset_clipped: usize,
    /// Clips of personal names (left out of a published pack): count, bytes.
    pub personal: (usize, u64),
    /// Integrated loudness of the decoded clips: min, median, max, LUFS.
    pub lufs: (f64, f64, f64),
    /// Highest true peak of a decoded clip, dBTP.
    pub true_peak_max_dbtp: f64,
    /// Clips whose peaks the limiter brought down; largest reduction, dB.
    pub limited: (usize, f64),
    /// Clips left under the target because the limiter reached its bound.
    pub capped: usize,
    /// Limiter look-ahead, release and largest reduction, ms, ms, dB.
    pub limiter: (f64, f64, f64),
    /// pockettts.cpp wall time, s (model load included).
    pub tts_wall_s: f64,
    /// Model load, ms.
    pub tts_load_ms: f64,
    /// Encoding wall time, s.
    pub encode_wall_s: f64,
    /// Whole build wall time, s.
    pub total_wall_s: f64,
}

fn sha256_file(p: &Path) -> Result<String> {
    let mut f = std::fs::File::open(p).map_err(|e| Error::io(p, e))?;
    let mut h = Sha256::new();
    let mut buf = vec![0u8; 1 << 20];
    loop {
        let n = std::io::Read::read(&mut f, &mut buf).map_err(|e| Error::io(p, e))?;
        if n == 0 {
            break;
        }
        h.update(&buf[..n]);
    }
    Ok(hex::encode(h.finalize()))
}

/// Generates the voice layer of `site` for the pack names `names` of unknown provenance:
/// each name is public when the site's layers have it from a publishable source
/// ([`crate::sources::site_names`], [`SiteNames::classify`]), else personal; without the
/// layers, every name is personal as soon as one of `name_sources` is personal use
/// ([`SiteNames::unclassified`]). `name_sources` are written to `voice.meta.json` after
/// those of the voice. [`build_site`] takes the names with their provenance.
pub fn build(
    site: &Site,
    layout: &DataLayout,
    names: &PackNames,
    name_sources: &[SourceRef],
    cfg: &VoiceConfig,
) -> Result<VoiceBuild> {
    let split = match site_names(layout, site) {
        Ok(known) => SiteNames::classify(names, name_sources, &known),
        Err(_) => SiteNames::unclassified(names, name_sources),
    };
    build_site(site, layout, &split, cfg)
}

/// Generates the voice layer of `site`: every clip of the public names, and those of the
/// personal names, listed in `personal.json`.
pub fn build_site(
    site: &Site,
    layout: &DataLayout,
    names: &SiteNames,
    cfg: &VoiceConfig,
) -> Result<VoiceBuild> {
    let t0 = Instant::now();
    let dir = layout.layer_dir(site, &cfg.lang.layer())?;
    let clips_dir = dir.join("clips");
    DataLayout::ensure(&clips_dir)?;

    let m = manifest_split_in(&names.public, &names.personal, cfg.lang);
    // Engines: the voice of the language, and the French one for the French proper names
    // of another language (VO6: an English pack says « Greffier » as the French voice does,
    // then « Blue trail. » in English).
    let mut engines = vec![cfg.tts.clone()];
    if let Some(n) = &cfg.names_tts {
        engines.push(n.clone());
    }
    let counters: Vec<PocketText> = engines
        .iter()
        .map(|e| PocketText::from_gguf(&e.model).map_err(Error::from))
        .collect::<Result<_>>()?;
    // Units: each distinct (engine, text) synthesised once; a clip is one or more units.
    let mut units: Vec<(usize, String, usize)> = Vec::new();
    let mut unit_of: std::collections::HashMap<(usize, String), usize> =
        std::collections::HashMap::new();
    let mut clips: Vec<(String, ClipKind, String, Vec<usize>)> = Vec::new();
    for (id, (kind, t)) in &m.clips {
        let mut parts = Vec::new();
        for (engine, text) in clip_parts(id, *kind, t, cfg) {
            let n = counters[engine].count(&text);
            if n > MAX_TOKENS || n == 0 {
                return Err(Error::Clip {
                    id: id.clone(),
                    message: format!("{n} tokens (budget {MAX_TOKENS}): {text}"),
                });
            }
            let next = units.len();
            let u = *unit_of.entry((engine, text.clone())).or_insert(next);
            if u == next {
                units.push((engine, text, n));
            }
            parts.push(u);
        }
        clips.push((id.clone(), *kind, t.clone(), parts));
    }

    // #129: the clips already made, for this site or another one, from the same parts by
    // the same engines with the same settings, are taken from the cache of the data
    // directory (`cache/voice/`): a phrase that did not change is never synthesised again,
    // and the fixed phrases and values, the same on every site, are synthesised once.
    let cache = ClipCache::new(layout)?;
    let engine_keys: Vec<EngineKey> = engines.iter().map(EngineKey::of).collect::<Result<_>>()?;
    let keys: Vec<String> = clips
        .iter()
        .map(|(_, _, _, parts)| {
            let parts: Vec<(&EngineKey, &str)> = parts
                .iter()
                .map(|&p| (&engine_keys[units[p].0], units[p].1.as_str()))
                .collect();
            clip_key(&parts, cfg)
        })
        .collect();
    let mut cached: Vec<Option<CachedClip>> = keys.iter().map(|k| cache.get(k)).collect();
    let (mut tts_wall_s, mut tts_load_ms, mut passes) = (0.0, f64::NAN, Vec::new());
    let (mut encode_wall_s, mut made_clips) = (0.0, 0);
    if cached.iter().any(Option::is_none) {
        // One synthesis at a time on the data directory (memory: one Pocket TTS process,
        // whatever the number of sites built at once), and what another build made while
        // this one waited is taken.
        let _lock = skimap_common::output::FileLock::lock(&cache.lock_path())?;
        for (c, k) in cached.iter_mut().zip(&keys) {
            if c.is_none() {
                *c = cache.get(k);
            }
        }
        let mut needed = vec![false; units.len()];
        for ((_, _, _, parts), c) in clips.iter().zip(&cached) {
            if c.is_none() {
                for &p in parts {
                    needed[p] = true;
                }
            }
        }
        // Generation with quality control: a unit whose speech is cut at the start (or
        // opens on the cold-start click) or never reaches the end of speech is generated
        // again with the next seed, up to SEED_ATTEMPTS seeds; failing that, the latest
        // onset is kept and flagged.
        let mut best: Vec<Option<(u32, Utterance, f64)>> = vec![None; units.len()];
        let mut done = vec![false; units.len()];
        for (engine, base) in engines.iter().enumerate() {
            let mut pending: Vec<usize> = (0..units.len())
                .filter(|&i| needed[i] && units[i].0 == engine)
                .collect();
            for attempt in 0..SEED_ATTEMPTS {
                if pending.is_empty() {
                    break;
                }
                let tts = PocketTts {
                    seed: base.seed.wrapping_add(attempt),
                    ..base.clone()
                };
                let lines: Vec<String> = pending.iter().map(|&i| units[i].1.clone()).collect();
                let (utts, stats) = tts.synthesize(&lines)?;
                tts_wall_s += stats.wall_s;
                if tts_load_ms.is_nan() {
                    tts_load_ms = stats.load_ms;
                }
                if passes.len() <= attempt as usize {
                    passes.push(0);
                }
                passes[attempt as usize] += pending.len();
                for (&i, u) in pending.iter().zip(utts) {
                    let (_, t, n) = &units[i];
                    if u.chunk_tokens != [*n] {
                        return Err(Error::Clip {
                            id: t.clone(),
                            message: format!(
                                "pockettts.cpp read {:?} tokens, the Rust port counts {n}: {t}",
                                u.chunk_tokens
                            ),
                        });
                    }
                    let onset =
                        speech_onset_ms(&u.samples, SAMPLE_RATE, &cfg.shape).unwrap_or(-1.0);
                    if !u.missing_eos && onset >= MIN_ONSET_MS {
                        done[i] = true;
                    }
                    let better = best[i].as_ref().is_none_or(|(_, b, o)| {
                        (b.missing_eos && !u.missing_eos)
                            || (b.missing_eos == u.missing_eos && onset > *o)
                    });
                    if better {
                        best[i] = Some((tts.seed, u, onset));
                    }
                }
                pending.retain(|&i| !done[i]);
            }
        }

        // Samples, shaping, seed kept, onset maybe cut.
        type ShapedUnit = (Vec<i16>, crate::audio::Shaped, u32, bool);
        let mut shaped_units: Vec<Option<ShapedUnit>> = Vec::with_capacity(units.len());
        for (((_, t, _), b), clean) in units.iter().zip(best).zip(&done) {
            let Some((seed, u, _)) = b else {
                shaped_units.push(None);
                continue;
            };
            if u.missing_eos {
                return Err(Error::Clip {
                    id: t.clone(),
                    message: format!("no end of speech with {SEED_ATTEMPTS} seeds: {t}"),
                });
            }
            let Some((samples, s)) = shape(&u.samples, SAMPLE_RATE, &cfg.shape) else {
                return Err(Error::Clip {
                    id: t.clone(),
                    message: format!("silent clip: {t}"),
                });
            };
            shaped_units.push(Some((samples, s, seed, !*clean)));
        }
        let unit = |p: usize| {
            shaped_units[p]
                .as_ref()
                .expect("needed units are synthesised")
        };
        let gap = (crate::bank::Pause::Short.ms() * SAMPLE_RATE / 1000) as usize;
        let mut made = Vec::new();
        for (i, (_, _, _, parts)) in clips.iter().enumerate() {
            if cached[i].is_some() {
                continue;
            }
            let mut samples: Vec<i16> = Vec::new();
            for (k, &p) in parts.iter().enumerate() {
                if k > 0 {
                    samples.extend(std::iter::repeat_n(0i16, gap));
                }
                samples.extend_from_slice(&unit(p).0);
            }
            let first = unit(parts[0]);
            let last = unit(parts[parts.len() - 1]);
            let s = CachedClip {
                duration_ms: (samples.len() as u64 * 1000 / u64::from(SAMPLE_RATE)) as u32,
                bytes: 0,
                tokens: parts.iter().map(|&p| units[p].2).sum(),
                lead_trim_ms: first.1.lead_ms.round() as u32,
                tail_trim_ms: last.1.tail_ms.round() as u32,
                // Level of the first part; the loudness gain is added by the cache.
                gain_db: first.1.gain_db,
                end_burst: parts.iter().any(|&p| unit(p).1.end_burst),
                seed: first.2,
                onset_clipped: parts.iter().any(|&p| unit(p).3),
                loudness_lufs: f64::NAN,
                true_peak_dbtp: f64::NAN,
                limiter_db: 0.0,
                loudness_capped: false,
            };
            made.push((i, samples, s));
        }

        let t_enc = Instant::now();
        let made: Vec<(usize, CachedClip)> = made
            .into_par_iter()
            .map(|(i, samples, s)| {
                let c = cache.put(&clips[i].0, &keys[i], &samples, s, cfg)?;
                Ok((i, c))
            })
            .collect::<Result<_>>()?;
        encode_wall_s = t_enc.elapsed().as_secs_f64();
        made_clips = made.len();
        for (i, c) in made {
            cached[i] = Some(c);
        }
    }

    // The layer: every clip of the manifest from the cache, and nothing else.
    let entries: Vec<ClipEntry> = clips
        .par_iter()
        .zip(&keys)
        .zip(&cached)
        .map(|(((id, kind, t, _), key), c)| {
            let c = c.as_ref().expect("every clip is cached or made");
            let file = format!("clips/{id}.opus");
            cache.copy_to(key, c, &dir.join(&file))?;
            Ok(ClipEntry {
                id: id.clone(),
                kind: *kind,
                text: t.clone(),
                file,
                duration_ms: c.duration_ms,
                bytes: c.bytes,
                tokens: c.tokens,
                lead_trim_ms: c.lead_trim_ms,
                tail_trim_ms: c.tail_trim_ms,
                gain_db: c.gain_db,
                end_burst: c.end_burst,
                seed: c.seed,
                onset_clipped: c.onset_clipped,
                loudness_lufs: Some(c.loudness_lufs),
                true_peak_dbtp: Some(c.true_peak_dbtp),
                limiter_db: Some(c.limiter_db),
                loudness_capped: c.loudness_capped,
            })
        })
        .collect::<Result<_>>()?;
    let wanted: std::collections::HashSet<String> =
        clips.iter().map(|(id, ..)| format!("{id}.opus")).collect();
    let rd = std::fs::read_dir(&clips_dir).map_err(|e| Error::io(&clips_dir, e))?;
    for e in rd.flatten() {
        if !wanted.contains(e.file_name().to_string_lossy().as_ref()) {
            let p = e.path();
            std::fs::remove_file(&p).map_err(|e| Error::io(&p, e))?;
        }
    }

    let vm = VoiceManifest {
        format: 1,
        lang: cfg.lang,
        voice: cfg.tts.voice.clone(),
        model: cfg
            .tts
            .model
            .file_name()
            .map(|f| f.to_string_lossy().into_owned())
            .unwrap_or_default(),
        model_sha256: sha256_file(&cfg.tts.model)?,
        seed: cfg.tts.seed,
        sample_rate: SAMPLE_RATE,
        opus_kbps: cfg.ffmpeg.kbps,
        loudness_target: Some((cfg.loudness.lufs, cfg.loudness.true_peak_dbtp)),
        pauses_ms: (
            crate::bank::Pause::Short.ms(),
            crate::bank::Pause::Long.ms(),
        ),
        clips: entries,
    };
    write_json(&dir.join("manifest.json"), &vm)?;
    let personal = PersonalClips {
        note: "clips des noms lus seulement dans des sources à usage personnel : écartés d'un pack publié (sans personal_sources)".into(),
        sources: names.personal_sources.iter().map(|s| s.name.clone()).collect(),
        clips: m.personal.iter().cloned().collect(),
    };
    write_json(&dir.join(PERSONAL_FILE), &personal)?;

    let mut per_kind = Vec::new();
    for k in [ClipKind::Fixed, ClipKind::Value, ClipKind::Name] {
        let it = vm.clips.iter().filter(|c| c.kind == k);
        per_kind.push((
            k,
            it.clone().count(),
            it.clone().map(|c| c.bytes).sum(),
            it.map(|c| u64::from(c.duration_ms)).sum(),
        ));
    }
    let mut leads: Vec<u32> = vm.clips.iter().map(|c| c.lead_trim_ms).collect();
    leads.sort_unstable();
    let mut lufs: Vec<f64> = vm.clips.iter().filter_map(|c| c.loudness_lufs).collect();
    lufs.sort_by(f64::total_cmp);
    let limits: Vec<f64> = vm
        .clips
        .iter()
        .filter_map(|c| c.limiter_db)
        .filter(|&d| d > 0.0)
        .collect();
    let summary = VoiceBuild {
        dir,
        per_kind,
        total_bytes: vm.clips.iter().map(|c| c.bytes).sum(),
        total_audio_s: vm
            .clips
            .iter()
            .map(|c| f64::from(c.duration_ms))
            .sum::<f64>()
            / 1000.0,
        max_tokens: vm.clips.iter().map(|c| c.tokens).max().unwrap_or(0),
        lead_trim_ms: (
            leads.first().copied().unwrap_or(0),
            leads.get(leads.len() / 2).copied().unwrap_or(0),
            leads.last().copied().unwrap_or(0),
        ),
        end_bursts: vm.clips.iter().filter(|c| c.end_burst).count(),
        passes,
        made_clips,
        reused_clips: vm.clips.len() - made_clips,
        onset_clipped: vm.clips.iter().filter(|c| c.onset_clipped).count(),
        personal: (
            vm.clips.iter().filter(|c| m.is_personal(&c.id)).count(),
            vm.clips
                .iter()
                .filter(|c| m.is_personal(&c.id))
                .map(|c| c.bytes)
                .sum(),
        ),
        lufs: (
            lufs.first().copied().unwrap_or(f64::NAN),
            lufs.get(lufs.len() / 2).copied().unwrap_or(f64::NAN),
            lufs.last().copied().unwrap_or(f64::NAN),
        ),
        true_peak_max_dbtp: vm
            .clips
            .iter()
            .filter_map(|c| c.true_peak_dbtp)
            .fold(f64::NEG_INFINITY, f64::max),
        limited: (limits.len(), limits.iter().copied().fold(0.0, f64::max)),
        capped: vm.clips.iter().filter(|c| c.loudness_capped).count(),
        limiter: (
            cfg.loudness.lookahead_ms,
            cfg.loudness.release_ms,
            cfg.loudness.max_limiting_db,
        ),
        tts_wall_s,
        tts_load_ms,
        encode_wall_s,
        total_wall_s: t0.elapsed().as_secs_f64(),
    };
    write_meta(site, &summary, &vm, names)?;
    Ok(summary)
}

/// Writes `voice.meta.json` in the common layer schema (`skimap_common::meta::LayerMeta`).
fn write_meta(
    site: &Site,
    b: &VoiceBuild,
    vm: &VoiceManifest,
    names: &SiteNames,
) -> Result<PathBuf> {
    let mut meta = LayerMeta::new(vm.lang.layer(), site.id);
    meta.tickets = vec!["VO3 (#85)".into(), "VO6 (#129)".into()];
    meta.validity = Some(
        "jusqu'au prochain changement des noms du pack (pistes, refuges, lieux, zones)".into(),
    );
    meta.sources = voice_sources(&vm.voice, vm.lang);
    meta.sources.extend_from_slice(&names.public_sources);
    meta.sources
        .extend(names.personal_sources.iter().cloned().map(|mut s| {
            s.personal_use_only = true;
            let n = "seulement les clips de personal.json, écartés d'un pack publié";
            s.note = Some(match s.note.take() {
                Some(x) => format!("{x} ; {n}"),
                None => n.to_owned(),
            });
            s
        }));
    let kinds = |k: ClipKind| b.per_kind.iter().find(|p| p.0 == k).map_or(0, |p| p.1);
    meta.files = vec![
        FileMeta::new(
            "manifest.json",
            "manifeste des clips (skimap_voice::pack::VoiceManifest) : voix, modèle, graine, pauses, et pour chaque clip son texte et son fichier",
        )
        .count(vm.clips.len())
        .properties([
            ("clips[].id", "identifiant du clip (celui de skimap_voice::bank)"),
            ("clips[].kind", "fixed (phrase fixe), value (valeur sur une grille), name (nom du pack)"),
            ("clips[].text", "texte prononcé"),
            ("clips[].file", "fichier Ogg/Opus, relatif au dossier de la couche"),
            ("clips[].duration_ms", "durée après coupe, ms"),
            ("clips[].bytes", "taille du fichier, octets"),
            ("clips[].tokens", "tokens Pocket TTS (vérifiés contre le journal de pockettts.cpp)"),
            ("clips[].lead_trim_ms / tail_trim_ms", "silence coupé au début / à la fin, ms"),
            ("clips[].gain_db", "gain appliqué à la synthèse, dB (niveau des parties, puis sonie)"),
            ("clips[].end_burst", "son coupé de fin de génération retiré"),
            ("clips[].seed", "graine du bruit de la génération gardée"),
            ("clips[].onset_clipped", "attaque peut-être coupée après toutes les graines essayées"),
            ("clips[].loudness_lufs", "sonie intégrée du fichier décodé (UIT-R BS.1770-4), LUFS"),
            ("clips[].true_peak_dbtp", "crête vraie du fichier décodé (suréchantillonnée 4 fois), dBTP"),
            ("clips[].limiter_db", "réduction de crête la plus forte du limiteur, dB (0 : non limité)"),
            ("clips[].loudness_capped", "limiteur à sa borne : clip un peu sous la sonie visée (première syllabe bien plus forte que la suite)"),
            ("loudness_target", "sonie de chaque clip (LUFS) et crête vraie maximale (dBTP)"),
        ]),
        FileMeta {
            format: Some(format!(
                "Ogg/Opus mono, {} kbit/s, {} Hz avant encodage",
                vm.opus_kbps, vm.sample_rate
            )),
            bytes: Some(b.total_bytes),
            ..FileMeta::new(
                "clips/<id>.opus",
                "un clip par entrée du manifeste ; silence de début et de fin coupé, parole compressée, sonie normalisée (-10 LUFS, crête vraie ≤ -1 dBTP)",
            )
            .count(vm.clips.len())
        },
        FileMeta::new(
            PERSONAL_FILE,
            "clips des noms lus seulement dans des sources à usage personnel (Biodiv'sports, plans des pistes) : écartés d'un pack publié (sans personal_sources)",
        )
        .count(b.personal.0)
        .properties([
            ("clips", "identifiants des clips, triés"),
            ("sources", "sources à usage personnel de ces noms"),
        ]),
    ];
    meta.notes = vec![
        "Clips générés sur le poste par pockettts.cpp (sous-processus), un appel par passe ; un clip dont l'attaque est coupée ou sans fin de parole est refait avec la graine suivante.".into(),
        "Tout texte absent du manifeste est lu par la voix Android (repli).".into(),
        format!(
            "Sonie : chaque clip à {} LUFS intégrés (UIT-R BS.1770-4 / EBU R128) et crête vraie ≤ {} dBTP, aussi fort que la parole peut l'être sous ce plafond (annonces audibles au volume Multimédia habituel d'un téléphone) ; un compresseur de parole (3:1 au-dessus des voyelles fortes, seuil relatif à la sonie du clip) rapproche les syllabes fortes du reste, puis un limiteur doux (anticipation {} ms, relâchement {} ms, au plus {} dB) abaisse les crêtes avant encodage, un clip qui demanderait plus reste un peu sous la cible ; mesure vérifiée sur le fichier Opus décodé à 48 kHz (#179).",
            vm.loudness_target.map_or(f64::NAN, |t| t.0),
            vm.loudness_target.map_or(f64::NAN, |t| t.1),
            b.limiter.0,
            b.limiter.1,
            b.limiter.2,
        ),
        "Les clips des noms lus seulement dans des sources à usage personnel (Biodiv'sports, plans des pistes) sont listés dans personal.json ; le pack les écarte sans personal_sources.".into(),
    ];
    meta.parameters = serde_json::json!({
        "lang": vm.lang.code(),
        "voice": vm.voice,
        "model": vm.model,
        "model_sha256": vm.model_sha256,
        "seed": vm.seed,
        "seed_attempts": SEED_ATTEMPTS,
        "max_tokens": MAX_TOKENS,
        "sample_rate_hz": vm.sample_rate,
        "opus_kbps": vm.opus_kbps,
        "pauses_ms": [vm.pauses_ms.0, vm.pauses_ms.1],
        "loudness_target_lufs": vm.loudness_target.map(|t| t.0),
        "true_peak_max_dbtp": vm.loudness_target.map(|t| t.1),
        "limiter_lookahead_release_ms": [b.limiter.0, b.limiter.1],
        "limiter_max_reduction_db": b.limiter.2,
    });
    meta.stats = serde_json::json!({
        "clips": vm.clips.len(),
        "clips_fixed": kinds(ClipKind::Fixed),
        "clips_value": kinds(ClipKind::Value),
        "clips_name": kinds(ClipKind::Name),
        "clips_personal": b.personal.0,
        "bytes_personal": b.personal.1,
        "names": {
            "site": names.public.site,
            "pistes": names.public.pistes.len(),
            "places": names.public.places.len(),
            "dates": names.public.dates.len(),
            "status_pistes": names.public.status_pistes,
        },
        "names_personal": {
            "pistes": names.personal.pistes.len(),
            "places": names.personal.places.len(),
            "dates": names.personal.dates.len(),
        },
        "bytes": b.total_bytes,
        "audio_s": (b.total_audio_s * 10.0).round() / 10.0,
        "max_tokens": b.max_tokens,
        "lead_trim_ms_min_median_max": [b.lead_trim_ms.0, b.lead_trim_ms.1, b.lead_trim_ms.2],
        "end_bursts": b.end_bursts,
        "passes": b.passes,
        "made_clips": b.made_clips,
        "reused_clips": b.reused_clips,
        "onset_clipped": b.onset_clipped,
        "lufs_min_median_max": [round2(b.lufs.0), round2(b.lufs.1), round2(b.lufs.2)],
        "true_peak_max_dbtp": round2(b.true_peak_max_dbtp),
        "clips_limited": b.limited.0,
        "limiter_max_db": round2(b.limited.1),
        "clips_loudness_capped": b.capped,
        "tts_wall_s": (b.tts_wall_s * 100.0).round() / 100.0,
        "encode_wall_s": (b.encode_wall_s * 100.0).round() / 100.0,
        "total_wall_s": (b.total_wall_s * 100.0).round() / 100.0,
    });
    Ok(meta.write(&b.dir)?)
}

fn round2(x: f64) -> f64 {
    (x * 100.0).round() / 100.0
}

/// Attempts of [`encode_levelled`].
const LEVEL_ATTEMPTS: usize = 6;

/// Brings a clip to the loudness target ([`normalize`]), encodes it to `path` and checks
/// the decoded file, what the phone plays. The encoder moves the loudness and the peaks a
/// little (up to +1.5 dB on the true peak of a sibilant at 24 kbit/s): a file off the
/// target is levelled again with the aim and the limiter ceiling corrected by what was
/// measured. When no attempt is within the tolerance, the attempt under the peak ceiling
/// nearest the target is kept if it is within twice the tolerance. Deterministic: the same
/// samples go through the same attempts and give the same file.
pub fn encode_levelled(
    id: &str,
    samples: &[i16],
    path: &Path,
    cfg: &VoiceConfig,
) -> Result<(Normalized, Loudness)> {
    let t = cfg.loudness;
    let level = |aim: &Target, ceiling: f64| -> Result<(Normalized, Loudness)> {
        let (pcm, n) = normalize(samples, SAMPLE_RATE, aim, ceiling).map_err(|e| Error::Clip {
            id: id.to_owned(),
            message: e.to_string(),
        })?;
        cfg.ffmpeg.encode_opus(&pcm, SAMPLE_RATE, path)?;
        let d = measure(&cfg.ffmpeg.decode(path, MEASURE_RATE)?, MEASURE_RATE)?;
        Ok((n, d))
    };
    let mut aim = t;
    let mut ceiling = t.ceiling_dbtp();
    // Best attempt under the peak ceiling: loudness miss, aim, ceiling.
    let mut best: Option<(f64, Target, f64)> = None;
    let mut last = None;
    for k in 0..LEVEL_ATTEMPTS {
        let (n, d) = level(&aim, ceiling)?;
        if t.accepts_level(&d, t.true_peak_dbtp, n.capped) {
            return Ok((n, d));
        }
        let miss = (d.lufs - t.lufs).abs();
        if d.true_peak_dbtp <= t.true_peak_dbtp && best.is_none_or(|b| miss < b.0) {
            best = Some((miss, aim, ceiling));
        }
        if d.true_peak_dbtp > t.true_peak_dbtp {
            ceiling -= d.true_peak_dbtp - t.true_peak_dbtp + 0.1;
        }
        if !n.capped {
            // Damped after the first correction: the encoder's offset is not exactly
            // the same from one level to the next.
            let step = if k == 0 { 1.0 } else { 0.5 };
            aim.lufs += step * (t.lufs - d.lufs);
        }
        last = Some(d);
    }
    if let Some((miss, aim, ceiling)) = best
        && miss <= 2.0 * t.tolerance_lu
    {
        return level(&aim, ceiling);
    }
    let d = last.expect("at least one attempt");
    Err(Error::Clip {
        id: id.to_owned(),
        message: format!(
            "decoded clip at {:.2} LUFS, {:.2} dBTP after {LEVEL_ATTEMPTS} attempts (target {} LUFS ± {}, ceiling {} dBTP)",
            d.lufs, d.true_peak_dbtp, t.lufs, t.tolerance_lu, t.true_peak_dbtp
        ),
    })
}

fn write_json(path: &Path, v: &impl Serialize) -> Result<()> {
    let b = serde_json::to_vec_pretty(v).map_err(|source| Error::Json {
        path: path.to_owned(),
        source,
    })?;
    Ok(skimap_common::output::write_bytes(path, &b)?)
}

/// Rate the clips are decoded at to be measured: that of Opus, the phone's decoder output.
pub const MEASURE_RATE: u32 = 48_000;

/// Loudness of every clip of the voice layer in `dir`, decoded as the phone decodes it
/// (Ogg/Opus at 48 kHz), in manifest order.
pub fn measure_layer(dir: &Path, ffmpeg: &Ffmpeg) -> Result<Vec<(String, Loudness)>> {
    let vm = VoiceManifest::read(dir)?;
    vm.clips
        .par_iter()
        .map(|c| {
            let pcm = ffmpeg.decode(&dir.join(&c.file), MEASURE_RATE)?;
            Ok((c.id.clone(), measure(&pcm, MEASURE_RATE)?))
        })
        .collect()
}

/// An assembled announcement.
#[derive(Debug, Clone, Serialize)]
pub struct Assembled {
    /// Text of the announcement.
    pub text: String,
    /// Clip ids played.
    pub clips: Vec<String>,
    /// Duration, s.
    pub duration_s: f64,
    /// Files written (WAV, Ogg/Opus).
    pub files: Vec<PathBuf>,
}

/// Assembles `a` as the phone does: decodes each Ogg/Opus clip of the layer in `dir`,
/// concatenates them with the pauses of the announcement, and writes `<stem>.wav` and
/// `<stem>.opus`. Fails if a clip is missing (the phone would use the fallback voice).
pub fn assemble(
    dir: &Path,
    vm: &VoiceManifest,
    a: &Announcement,
    ffmpeg: &Ffmpeg,
    stem: &Path,
) -> Result<Assembled> {
    let mut out: Vec<i16> = Vec::new();
    let sr = vm.sample_rate;
    for (i, s) in a.segments.iter().enumerate() {
        let e = vm.get(&s.clip.id).ok_or_else(|| Error::Clip {
            id: s.clip.id.clone(),
            message: "not in the pack (fallback voice)".into(),
        })?;
        if e.text != s.clip.text {
            return Err(Error::Clip {
                id: s.clip.id.clone(),
                message: format!("pack text {:?} differs from {:?}", e.text, s.clip.text),
            });
        }
        out.extend(ffmpeg.decode(&dir.join(&e.file), sr)?);
        if i + 1 < a.segments.len() {
            out.extend(std::iter::repeat_n(
                0i16,
                (s.pause.ms() * sr / 1000) as usize,
            ));
        }
    }
    let wav = stem.with_extension("wav");
    let opus = stem.with_extension("opus");
    if let Some(p) = stem.parent() {
        DataLayout::ensure(p)?;
    }
    write_wav(&wav, &out, sr)?;
    ffmpeg.encode_opus(&out, sr, &opus)?;
    Ok(Assembled {
        text: a.text(),
        clips: a.clip_ids().into_iter().map(str::to_owned).collect(),
        duration_s: out.len() as f64 / f64::from(sr),
        files: vec![wav, opus],
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::names::{Colour, PisteName};

    #[test]
    fn meta_follows_the_common_schema() {
        let dir = tempfile::tempdir().unwrap();
        let clip = |id: &str, kind, bytes| ClipEntry {
            id: id.into(),
            kind,
            text: "Texte.".into(),
            file: format!("clips/{id}.opus"),
            duration_ms: 500,
            bytes,
            tokens: 3,
            lead_trim_ms: 90,
            tail_trim_ms: 40,
            gain_db: 1.5,
            end_burst: false,
            seed: 42,
            onset_clipped: false,
            loudness_lufs: Some(-14.0),
            true_peak_dbtp: Some(-2.0),
            limiter_db: Some(0.0),
            loudness_capped: false,
        };
        let vm = VoiceManifest {
            format: 1,
            lang: Lang::Fr,
            voice: "estelle".into(),
            model: "pocket-tts-french-Q8_0.gguf".into(),
            model_sha256: "e7".into(),
            seed: 42,
            sample_rate: SAMPLE_RATE,
            opus_kbps: 24,
            loudness_target: Some((-14.0, -1.0)),
            pauses_ms: (150, 400),
            clips: vec![
                clip("arrivee", ClipKind::Fixed, 1000),
                clip("piste.greffier.noire", ClipKind::Name, 2000),
            ],
        };
        let b = VoiceBuild {
            dir: dir.path().to_owned(),
            per_kind: vec![
                (ClipKind::Fixed, 1, 1000, 500),
                (ClipKind::Value, 0, 0, 0),
                (ClipKind::Name, 1, 2000, 500),
            ],
            total_bytes: 3000,
            total_audio_s: 1.0,
            max_tokens: 3,
            lead_trim_ms: (90, 90, 90),
            end_bursts: 0,
            passes: vec![2],
            made_clips: 2,
            reused_clips: 0,
            onset_clipped: 0,
            personal: (1, 2000),
            lufs: (-14.2, -14.0, -13.8),
            true_peak_max_dbtp: -1.2,
            limited: (1, 2.5),
            capped: 0,
            limiter: (5.0, 60.0, 6.0),
            tts_wall_s: 1.0,
            tts_load_ms: 250.0,
            encode_wall_s: 0.1,
            total_wall_s: 1.2,
        };
        let osm = SourceRef::new("OSM", "https://example.org", "ODbL 1.0", "© OSM");
        let plan = SourceRef::new("Plan des pistes", "https://example.org/p", "?", "P");
        let names = SiteNames {
            public: PackNames {
                site: "Chapelle-des-Bois".into(),
                pistes: vec![],
                places: vec![],
                dates: vec![],
                status_pistes: 1,
            },
            personal: PackNames {
                pistes: vec![PisteName::new("Greffier", Some(Colour::Black))],
                ..PackNames::default()
            },
            public_sources: vec![osm.clone()],
            personal_sources: vec![plan],
        };
        let path = write_meta(
            skimap_common::site::site("chapelle-des-bois").expect("evaluation site"),
            &b,
            &vm,
            &names,
        )
        .unwrap();
        assert_eq!(path, dir.path().join("voice.meta.json"));
        let m = LayerMeta::read(&path).unwrap();
        assert_eq!(
            (m.layer.as_str(), m.site.as_str()),
            ("voice", "chapelle-des-bois")
        );
        assert_eq!(
            m.sources.len(),
            5,
            "model, engine, voice estelle, then the names"
        );
        assert_eq!(m.sources[3], osm);
        assert!(!m.sources[3].personal_use_only);
        assert!(
            m.sources[4].personal_use_only,
            "marked even if the caller did not"
        );
        assert_eq!(m.stats["clips_personal"], 1);
        assert_eq!(m.stats["names_personal"]["pistes"], 1);
        assert_eq!(m.files[2].name, PERSONAL_FILE);
        assert_eq!(m.files[2].count, Some(1));
        assert_eq!(m.files[0].name, "manifest.json");
        assert_eq!(m.files[1].count, Some(2));
        assert_eq!(m.files[1].bytes, Some(3000));
        assert_eq!(m.parameters["voice"], "estelle");
        assert_eq!(m.stats["clips_name"], 1);
        assert_eq!(m.parameters["loudness_target_lufs"], -14.0);
        assert_eq!(m.stats["lufs_min_median_max"][1], -14.0);
        assert_eq!(m.stats["clips_limited"], 1);
        assert!(
            m.notes.iter().any(|n| n.contains("-14 LUFS")),
            "{:?}",
            m.notes
        );
        assert_eq!(m.stats["names"]["pistes"], 0);
    }

    /// A configuration whose engine files need not exist (nothing is synthesised).
    fn test_config() -> VoiceConfig {
        let tts = PocketTts {
            binary: "pocket-tts".into(),
            model: "model.gguf".into(),
            voices: "voices.gguf".into(),
            voice: "estelle".into(),
            device: None,
            seed: 42,
        };
        VoiceConfig {
            lang: Lang::Fr,
            tts,
            names_tts: None,
            ffmpeg: Ffmpeg {
                binary: "ffmpeg".into(),
                kbps: 24,
            },
            shape: Shape::default(),
            loudness: Target::default(),
        }
    }

    fn test_engine() -> EngineKey {
        EngineKey {
            model_sha256: "a".repeat(64),
            voices_sha256: "b".repeat(64),
            voice: "estelle".into(),
            seed: 42,
        }
    }

    /// The key a clip had in the cache before the loudness normalisation (#129 as merged,
    /// before #179): the same inputs, format 1, no loudness.
    fn key_before_loudness(parts: &[(&EngineKey, &str)], cfg: &VoiceConfig) -> String {
        let v = serde_json::json!({
            "format": 1,
            "parts": parts,
            "seed_attempts": SEED_ATTEMPTS,
            "min_onset_ms": MIN_ONSET_MS,
            "shape": format!("{:?}", cfg.shape),
            "sample_rate": SAMPLE_RATE,
            "opus_kbps": cfg.ffmpeg.kbps,
            "gap_ms": crate::bank::Pause::Short.ms(),
        });
        hex::encode(Sha256::digest(v.to_string().as_bytes()))
    }

    /// #179: the key of a clip follows the loudness normalisation (every field of the
    /// target, the version of the algorithm); a clip cached at the level of before is never
    /// served again.
    #[test]
    fn clip_key_follows_the_loudness_normalisation() {
        let e = test_engine();
        let parts = [(&e, "Arrivée.")];
        let cfg = test_config();
        let base = clip_key(&parts, &cfg);
        assert_eq!(base, clip_key(&parts, &cfg), "deterministic");
        assert_ne!(
            base,
            key_before_loudness(&parts, &cfg),
            "key of before #179"
        );
        let inputs = clip_key_inputs(&parts, &cfg);
        assert_eq!(inputs["format"], CACHE_FORMAT);
        assert_eq!(
            inputs["loudness"]["algorithm"],
            crate::loudness::ALGORITHM_VERSION
        );
        assert_eq!(inputs["loudness"]["attempts"], LEVEL_ATTEMPTS);
        assert_eq!(inputs["loudness"]["measure_rate"], MEASURE_RATE);
        // Another version of the algorithm, the same target: another key.
        let mut bumped = inputs.clone();
        bumped["loudness"]["algorithm"] = (crate::loudness::ALGORITHM_VERSION + 1).into();
        assert_ne!(inputs.to_string(), bumped.to_string());
        type Change = (&'static str, fn(&mut Target));
        let changes: [Change; 10] = [
            // The target of the first #179 version: -14 LUFS, no compression.
            ("version 1", |t| {
                t.lufs = -14.0;
                t.compressor.ratio = 1.0;
            }),
            ("compressor.ratio", |t| t.compressor.ratio = 4.0),
            ("compressor.threshold_lu", |t| {
                t.compressor.threshold_lu = -6.0
            }),
            ("lufs", |t| t.lufs = -16.0),
            ("true_peak_dbtp", |t| t.true_peak_dbtp = -2.0),
            ("tolerance_lu", |t| t.tolerance_lu = 0.25),
            ("margin_db", |t| t.margin_db = 0.75),
            ("lookahead_ms", |t| t.lookahead_ms = 3.0),
            ("release_ms", |t| t.release_ms = 80.0),
            ("max_limiting_db", |t| t.max_limiting_db = 4.0),
        ];
        let mut seen = std::collections::HashSet::from([base.clone()]);
        for (field, change) in changes {
            let mut c = test_config();
            change(&mut c.loudness);
            let k = clip_key(&parts, &c);
            assert!(seen.insert(k), "{field} does not change the key");
            assert_ne!(
                code_revision(Lang::Fr, Some(&c)),
                code_revision(Lang::Fr, Some(&cfg)),
                "{field}"
            );
        }
    }

    /// #179: a clip put in the cache before the loudness normalisation (under its key of
    /// then, with its description of then) is not taken after it, under either key, while
    /// a clip of now is.
    #[test]
    fn a_clip_cached_before_loudness_is_made_again() {
        let root = tempfile::tempdir().unwrap();
        let cache = ClipCache::new(&DataLayout::new(root.path())).unwrap();
        let e = test_engine();
        let parts = [(&e, "Arrivée.")];
        let cfg = test_config();
        let old_key = key_before_loudness(&parts, &cfg);
        let new_key = clip_key(&parts, &cfg);
        assert_ne!(old_key, new_key, "same key before and after #179");
        // The description a clip had in the cache before #179.
        let old_json = serde_json::json!({
            "duration_ms": 500, "bytes": 4, "tokens": 3, "lead_trim_ms": 10,
            "tail_trim_ms": 20, "gain_db": 6.5, "end_burst": false, "seed": 42,
            "onset_clipped": false,
        });
        let write = |key: &str, json: &serde_json::Value| {
            let (opus, js) = cache.paths(key);
            std::fs::create_dir_all(opus.parent().unwrap()).unwrap();
            std::fs::write(&opus, b"opus").unwrap();
            std::fs::write(&js, json.to_string()).unwrap();
        };
        write(&old_key, &old_json);
        assert!(
            cache.get(&new_key).is_none(),
            "old clip served under the new key"
        );
        assert!(cache.get(&old_key).is_none(), "old description read");
        // Even under the key of now, a description without loudness is not taken.
        write(&new_key, &old_json);
        assert!(
            cache.get(&new_key).is_none(),
            "description without loudness read"
        );
        // A clip of now is.
        let mut now = old_json.clone();
        now["loudness_lufs"] = (-14.02).into();
        now["true_peak_dbtp"] = (-1.4).into();
        now["limiter_db"] = 0.0.into();
        now["loudness_capped"] = false.into();
        write(&new_key, &now);
        let c = cache.get(&new_key).expect("clip of now");
        assert_eq!(c.loudness_lufs, -14.02);
    }

    /// A clip made for the cache is at the loudness target once decoded, and the same
    /// samples give the same file byte for byte in two caches (needs ffmpeg with libopus).
    #[test]
    fn cached_clip_is_levelled_and_reproducible() {
        let cfg = test_config();
        if std::process::Command::new(&cfg.ffmpeg.binary)
            .arg("-version")
            .output()
            .is_err()
        {
            eprintln!("ffmpeg absent: skipped");
            return;
        }
        // Speech-like: a 220 Hz carrier in 4 Hz syllables, about -24 LUFS.
        let samples: Vec<i16> = (0..SAMPLE_RATE as usize * 2)
            .map(|i| {
                let t = i as f64 / f64::from(SAMPLE_RATE);
                let syl = (std::f64::consts::TAU * 4.0 * t).sin().abs().powi(2);
                let v = syl
                    * (0.6 * (std::f64::consts::TAU * 220.0 * t).sin()
                        + 0.3 * (std::f64::consts::TAU * 660.0 * t).sin()
                        + 0.1 * (std::f64::consts::TAU * 1760.0 * t).sin());
                (3000.0 * v).round() as i16
            })
            .collect();
        let desc = CachedClip {
            duration_ms: 2000,
            bytes: 0,
            tokens: 3,
            lead_trim_ms: 0,
            tail_trim_ms: 0,
            gain_db: 1.25,
            end_burst: false,
            seed: 42,
            onset_clipped: false,
            loudness_lufs: f64::NAN,
            true_peak_dbtp: f64::NAN,
            limiter_db: 0.0,
            loudness_capped: false,
        };
        let key = clip_key(&[(&test_engine(), "Arrivée.")], &cfg);
        let mut files = Vec::new();
        for _ in 0..2 {
            let root = tempfile::tempdir().unwrap();
            let cache = ClipCache::new(&DataLayout::new(root.path())).unwrap();
            let c = cache
                .put("arrivee", &key, &samples, desc.clone(), &cfg)
                .unwrap();
            let t = cfg.loudness;
            assert!(
                (c.loudness_lufs - t.lufs).abs() <= 2.0 * t.tolerance_lu,
                "{c:?}"
            );
            assert!(c.true_peak_dbtp <= t.true_peak_dbtp, "{c:?}");
            assert!(c.gain_db > 1.25 + 5.0, "loudness gain added: {c:?}");
            assert_eq!(cache.get(&key), Some(c.clone()));
            let out = root.path().join("arrivee.opus");
            cache.copy_to(&key, &c, &out).unwrap();
            let decoded = measure(
                &cfg.ffmpeg.decode(&out, MEASURE_RATE).unwrap(),
                MEASURE_RATE,
            )
            .unwrap();
            assert!(
                (decoded.lufs - c.loudness_lufs).abs() < 0.01,
                "{decoded:?} {c:?}"
            );
            files.push((std::fs::read(&out).unwrap(), c));
        }
        assert_eq!(files[0], files[1], "two caches, two different clips");
    }
}
